    "Book": {
        "caption": "Add Book",
        "label": "Books",
        "icon": "book",
        "placeholder": "Search books by title, author, or ISBN...",
        "loadingText": "Searching OpenLibrary...",
        "resultTag": "SearchResult",
        "imageField": "draft_cover",
        "subtitle": "By <$text text={{{ [enlist{!!draft_author}search-replace:g[_],[ ]join[, ]] }}}/>"
    },
    "Comic": {
        "caption": "Add Comic",
        "label": "Comics",
        "icon": "comic",
        "apiKeyTiddler": "$:/plugins/mblackman/media-importer/configs/comicvine-api-key",
        "placeholder": "Search comic volumes...",
        "loadingText": "Searching ComicVine...",
        "resultTag": "ComicSearchResult",
        "imageField": "draft_image",
        "subtitle": "{{!!draft_publisher}}"
    },
    "Game": {
        "caption": "Add Game",
        "label": "Games",
        "icon": "game",
        "apiKeyTiddler": "$:/plugins/mblackman/media-importer/configs/rawg-api-key",
        "placeholder": "Search video games...",
        "loadingText": "Searching RAWG...",
        "resultTag": "GameSearchResult",
        "imageField": "draft_image",
        "subtitle": "{{!!draft_genres}}"
    },
    "Manga": {
        "caption": "Add Manga",
        "label": "Manga",
        "icon": "manga",
        "placeholder": "Search manga series...",
        "loadingText": "Searching AniList...",
        "resultTag": "MangaSearchResult",
        "imageField": "draft_image",
        "subtitle": "{{!!draft_author}}"
    },
    "Movie": {
        "caption": "Add Movie",
        "label": "Movies",
        "icon": "movie",
        "apiKeyTiddler": "$:/plugins/mblackman/media-importer/configs/tmdb-api-key",
        "placeholder": "Search movies...",
        "loadingText": "Searching TMDB...",
        "resultTag": "MovieSearchResult",
        "imageField": "draft_poster",
        "subtitle": "{{!!draft_overview}}"
    },
    "Music": {
        "caption": "Add Music",
        "label": "Music",
        "icon": "music",
        "placeholder": "Search albums, EPs, or artists...",
        "loadingText": "Searching MusicBrainz...",
        "resultTag": "MusicSearchResult",
        "imageField": "draft_cover",
        "subtitle": "By <$text text={{{ [enlist{!!draft_artist}search-replace:g[_],[ ]join[, ]] }}}/>"
    },
    "TV Show": {
        "caption": "Add TV Show",
        "label": "TV Shows",
        "icon": "tv",
        "apiKeyTiddler": "$:/plugins/mblackman/media-importer/configs/tmdb-api-key",
        "placeholder": "Search TV series...",
        "loadingText": "Searching TMDB...",
        "resultTag": "TVShowSearchResult",
        "imageField": "draft_poster",
        "subtitle": "{{!!draft_overview}}"
    }
}
